package com.inventra.backend.controller;
import com.inventra.backend.dto.*; import com.inventra.backend.service.InventoryCoreService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/warehouses/{warehouseId}/inventory") public class WarehouseInventoryController {private final InventoryCoreService s;public WarehouseInventoryController(InventoryCoreService s){this.s=s;}@GetMapping public java.util.List<InventoryResponse> all(@PathVariable String warehouseId){return s.allForWarehouse(warehouseId);}@GetMapping("/{productId}") public InventoryResponse get(@PathVariable String warehouseId,@PathVariable String productId){var x=s.get(warehouseId,productId);return new InventoryResponse(x.getId(),x.getWarehouseId(),x.getProductId(),x.getQuantity(),x.getReservedQuantity(),x.getAvailableQuantity());}@PostMapping("/adjust") public InventoryResponse adjust(@PathVariable String warehouseId,@Valid @RequestBody InventoryAdjustmentRequest r){return s.adjust(warehouseId,r);}@PostMapping("/transfer") public String transfer(@PathVariable String warehouseId,@Valid @RequestBody TransferRequest r){s.transfer(warehouseId,r.toWarehouseId(),r.productId(),r.quantity(),r.reason());return "Inventory transferred successfully";}}
